if 데이터길이 < {min_len}:
    매수 = False
elif not ({b1_start} <= 시분초 < {b1_end}):
    if not ({b1_end} <= 시분초 < {b2_end}):
        if not ({b2_end} <= 시분초 < {b3_end}):
