                    매수 = False
            else:
                매수 = False
    else:
        if {b2_cap_min} <= 시가총액 < {b2_cap_max}:
            if not (등락율 >= {b2_rate_min} and 등락율 <= {b2_rate_max} and 당일거래대금 >= {b2_day_money_min} and 초당거래대금 >= {b2_sec_money_min} and 현재가 >= 이동평균({b2_ma_win}, 1) * {b2_ma_mult} and 초당거래대금 >= 초당거래대금평균({b2_burst_win}, 1) * {b2_burst_mult} and 체결강도 >= {b2_strength_min} and 전일동시간비 >= {b2_prev_ratio_min}):
                매수 = False
        else:
            매수 = False
else:
    if 시가총액 < {b1_cap_max}:
        if not (등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max} and 당일거래대금 >= {b1_day_money_min} and 초당거래대금 >= {b1_sec_money_min} and 초당거래대금 >= 초당거래대금평균({b1_burst_win}, 1) * {b1_burst_mult} and 체결강도 >= {b1_strength_min} and 등락율각도({b1_angle_win}) >= {b1_angle_min}):
            매수 = False
    else:
        매수 = False
if 매수:
    self.Buy()

